27	pub struct Prompt {
28	    /// Conversation context input items.
29	    pub input: Vec<ResponseItem>,
30	
31	    /// Tools available to the model, including additional tools sourced from
32	    /// external MCP servers.
33	    pub(crate) tools: Vec<ToolSpec>,
34	
35	    /// Whether parallel tool calls are permitted for this prompt.
36	    pub(crate) parallel_tool_calls: bool,
37	
38	    pub base_instructions: BaseInstructions,
39	
40	    /// Optionally specify the personality of the model.
41	    pub personality: Option<Personality>,
