47	impl Prompt {
48	    pub(crate) fn get_formatted_input(&self) -> Vec<ResponseItem> {
49	        let mut input = self.input.clone();
50	
51	        // when using the *Freeform* apply_patch tool specifically, tool outputs
52	        // should be structured text, not json. Do NOT reserialize when using
53	        // the Function tool - note that this differs from the check above for
54	        // instructions. We declare the result as a named variable for clarity.
55	        let is_freeform_apply_patch_tool_present = self.tools.iter().any(|tool| match tool {
56	            ToolSpec::Freeform(f) => f.name == "apply_patch",
57	            _ => false,
58	        });
59	        if is_freeform_apply_patch_tool_present {
60	            reserialize_shell_outputs(&mut input);
61	        }
62	
63	        input
64	    }
65	}
66	
67	fn reserialize_shell_outputs(items: &mut [ResponseItem]) {
68	    let mut shell_call_ids: HashSet<String> = HashSet::new();
69	
70	    items.iter_mut().for_each(|item| match item {
71	        ResponseItem::LocalShellCall { call_id, id, .. } => {
72	            if let Some(identifier) = call_id.clone().or_else(|| id.clone()) {
73	                shell_call_ids.insert(identifier);
74	            }
75	        }
76	        ResponseItem::CustomToolCall {
77	            id: _,
78	            status: _,
79	            call_id,
80	            name,
81	            input: _,
82	        } => {
83	            if name == "apply_patch" {
84	                shell_call_ids.insert(call_id.clone());
85	            }
86	        }
87	        ResponseItem::FunctionCall { name, call_id, .. }
88	            if is_shell_tool_name(name) || name == "apply_patch" =>
89	        {
90	            shell_call_ids.insert(call_id.clone());
91	        }
92	        ResponseItem::FunctionCallOutput { call_id, output }
93	        | ResponseItem::CustomToolCallOutput { call_id, output } => {
94	            if shell_call_ids.remove(call_id)
95	                && let Some(structured) = output
96	                    .text_content()
97	                    .and_then(parse_structured_shell_output)
98	            {
99	                output.body = FunctionCallOutputBody::Text(structured);
100	            }
101	        }
102	        _ => {}
103	    })
104	}
105	
106	fn is_shell_tool_name(name: &str) -> bool {
107	    matches!(name, "shell" | "container.exec")
108	}
109	
110	#[derive(Deserialize)]
111	struct ExecOutputJson {
112	    output: String,
113	    metadata: ExecOutputMetadataJson,
114	}
115	
116	#[derive(Deserialize)]
117	struct ExecOutputMetadataJson {
118	    exit_code: i32,
119	    duration_seconds: f32,
120	}
121	
122	fn parse_structured_shell_output(raw: &str) -> Option<String> {
123	    let parsed: ExecOutputJson = serde_json::from_str(raw).ok()?;
124	    Some(build_structured_output(&parsed))
125	}
126	
127	fn build_structured_output(parsed: &ExecOutputJson) -> String {
128	    let mut sections = Vec::new();
129	    sections.push(format!("Exit code: {}", parsed.metadata.exit_code));
130	    sections.push(format!(
131	        "Wall time: {} seconds",
132	        parsed.metadata.duration_seconds
133	    ));
134	
135	    let mut output = parsed.output.clone();
136	    if let Some((stripped, total_lines)) = strip_total_output_header(&parsed.output) {
137	        sections.push(format!("Total output lines: {total_lines}"));
138	        output = stripped.to_string();
139	    }
140	
141	    sections.push("Output:".to_string());
142	    sections.push(output);
143	
144	    sections.join("\n")
145	}
146	
147	fn strip_total_output_header(output: &str) -> Option<(&str, u32)> {
148	    let after_prefix = output.strip_prefix("Total output lines: ")?;
149	    let (total_segment, remainder) = after_prefix.split_once('\n')?;
150	    let total_lines = total_segment.parse::<u32>().ok()?;
151	    let remainder = remainder.strip_prefix('\n').unwrap_or(remainder);
152	    Some((remainder, total_lines))
153	}
