141	async fn assert_compaction_uses_turn_lifecycle_id(codex: &std::sync::Arc<codex_core::CodexThread>) {
142	    let mut turn_started_id = None;
143	    let mut turn_completed_id = None;
144	    let mut compact_started_id = None;
145	    let mut compact_completed_id = None;
146	
147	    while turn_completed_id.is_none() {
148	        let event = codex.next_event().await.expect("next event");
149	        match event.msg {
150	            EventMsg::TurnStarted(_) => turn_started_id = Some(event.id.clone()),
151	            EventMsg::ItemStarted(ItemStartedEvent {
152	                item: TurnItem::ContextCompaction(_),
153	                ..
154	            }) => compact_started_id = Some(event.id.clone()),
155	            EventMsg::ItemCompleted(ItemCompletedEvent {
156	                item: TurnItem::ContextCompaction(_),
157	                ..
158	            }) => compact_completed_id = Some(event.id.clone()),
159	            EventMsg::TurnComplete(_) => turn_completed_id = Some(event.id.clone()),
160	            _ => {}
161	        }
162	    }
163	
164	    let turn_started_id = turn_started_id.expect("turn started id");
165	    let turn_completed_id = turn_completed_id.expect("turn complete id");
166	
167	    assert_eq!(
168	        turn_completed_id, turn_started_id,
169	        "turn start and complete should use the same event id"
170	    );
171	    assert_eq!(
172	        compact_started_id,
173	        Some(turn_started_id.clone()),
174	        "compaction item start should use the turn event id"
175	    );
176	    assert_eq!(
177	        compact_completed_id,
178	        Some(turn_started_id),
179	        "compaction item completion should use the turn event id"
180	    );
181	}
